#pragma once

#include <juce_audio_processors/juce_audio_processors.h>

// Factory banks, loaded from the text files in Resources/ (generated by tools/gen_presets.py).
// Each line: name <tab> category <tab> tags <tab> description <tab> values [<tab> kind]
// values: "param_id=value ..." plus "mx0=x,y,c;x,y,c..." curve tokens for the Matrix lanes.
namespace Presets
{
    struct Entry
    {
        juce::String name, category, description, values, kind;   // kind = "Category.recipe" (the sound family)
        juce::StringArray tags;
    };

    const std::vector<Entry>& factory();        // synth presets
    const std::vector<Entry>& matrixBank();     // Matrix (gate / shaper) presets
    const std::vector<Entry>& rackBank();       // Minirack presets
    const std::vector<Entry>& seeds();          // the word engine's sound library (every recipe variation)

    int count();
    juce::String name (int index);
    juce::String category (int index);
    juce::String description (int index);
    juce::StringArray tags (int index);
}
